import{_ as l,o as e,c as i,a0 as o}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"校园急救","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生课程/校园急救.md","filePath":"中山大学/新生课程/校园急救.md"}'),r={name:"中山大学/新生课程/校园急救.md"};function t(h,a,n,d,p,c){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="校园急救" tabindex="-1">校园急救 <a class="header-anchor" href="#校园急救" aria-label="Permalink to &quot;校园急救&quot;">​</a></h1><p>课程时间：2026.8.21 14:30~15:30</p><p>主讲：胡春林</p><h2 id="为什么要学急救" tabindex="-1">为什么要学急救 <a class="header-anchor" href="#为什么要学急救" aria-label="Permalink to &quot;为什么要学急救&quot;">​</a></h2><p>紧急事件频发，黄金时间短暂</p><p>大学生集体生活也会造成群体性意外</p><blockquote><p>也有法律保障原因</p></blockquote><h2 id="广州与中大校园急救特点" tabindex="-1">广州与中大校园急救特点 <a class="header-anchor" href="#广州与中大校园急救特点" aria-label="Permalink to &quot;广州与中大校园急救特点&quot;">​</a></h2><ol><li>广东温度原因</li><li>校园内（军训、实验室等）</li><li>饮食结构原因（海鲜丰富、凉茶文化）</li></ol><h2 id="临床常见急症快速识别" tabindex="-1">临床常见急症快速识别 <a class="header-anchor" href="#临床常见急症快速识别" aria-label="Permalink to &quot;临床常见急症快速识别&quot;">​</a></h2><p>问主诉（哪里不舒服）、看神志（清醒瞌睡）、看面色（苍白红润）、看呼吸（频率节律）、看循环（脉搏血压）</p><h2 id="胸痛与呼吸困难的识别" tabindex="-1">胸痛与呼吸困难的识别 <a class="header-anchor" href="#胸痛与呼吸困难的识别" aria-label="Permalink to &quot;胸痛与呼吸困难的识别&quot;">​</a></h2><p>致命性胸痛</p><ol><li>急性心梗：&gt;30min</li><li>主动脉夹层：撕裂样剧痛，向背部放射</li></ol><p>非致命性胸痛</p><ol><li>肋软骨炎/肋间神经痛：局部压缩</li><li>胸膜炎：深呼吸时加重</li></ol><p>急救要点</p><ol><li>半卧位休息</li><li>勿随意搬动、勿用力咳嗽</li><li>致命性胸痛拨打120，告知症状和位置</li></ol><h2 id="急性腹痛的识别与处理" tabindex="-1">急性腹痛的识别与处理 <a class="header-anchor" href="#急性腹痛的识别与处理" aria-label="Permalink to &quot;急性腹痛的识别与处理&quot;">​</a></h2><p>常见错误：喂止痛药、热敷、催吐 正确处理：禁食水、半卧位、尽快就医</p><h2 id="发热的识别与处理" tabindex="-1">发热的识别与处理 <a class="header-anchor" href="#发热的识别与处理" aria-label="Permalink to &quot;发热的识别与处理&quot;">​</a></h2><p>退烧不是重点，重点是识别原因</p><h2 id="头痛" tabindex="-1">头痛 <a class="header-anchor" href="#头痛" aria-label="Permalink to &quot;头痛&quot;">​</a></h2><p>良性头痛</p><ol><li>紧张性头痛</li><li>偏头痛：单侧搏动性，伴随恶心</li><li>颈源性头痛：颈椎姿势不良</li></ol><p>危险</p><ol><li>雷击性头痛</li></ol><h2 id="气道异物阻塞-识别" tabindex="-1">气道异物阻塞：识别 <a class="header-anchor" href="#气道异物阻塞-识别" aria-label="Permalink to &quot;气道异物阻塞：识别&quot;">​</a></h2><p>产生原因</p><ol><li>进食过快</li><li>吞食异物</li></ol><h2 id="广州气候与中暑概述" tabindex="-1">广州气候与中暑概述 <a class="header-anchor" href="#广州气候与中暑概述" aria-label="Permalink to &quot;广州气候与中暑概述&quot;">​</a></h2><p>广州气候特征：夏季长、最高温高、湿度大</p><p>中暑的定义：高温环境下体温调节失衡</p><h3 id="中暑分级与识别" tabindex="-1">中暑分级与识别 <a class="header-anchor" href="#中暑分级与识别" aria-label="Permalink to &quot;中暑分级与识别&quot;">​</a></h3><p>先兆中暑：口渴、头晕、多汗、四肢乏力</p><p>轻症中暑：面色潮红/苍白、恶心呕吐</p><h3 id="中暑现场急救处理" tabindex="-1">中暑现场急救处理 <a class="header-anchor" href="#中暑现场急救处理" aria-label="Permalink to &quot;中暑现场急救处理&quot;">​</a></h3><p>移至阴凉通风处、解开衣服</p><blockquote><p>不要赛冰块</p></blockquote><h2 id="出血与止血技术" tabindex="-1">出血与止血技术 <a class="header-anchor" href="#出血与止血技术" aria-label="Permalink to &quot;出血与止血技术&quot;">​</a></h2><p>案例：手部出血不止</p><p>先压迫止血5分钟，同时抬高患肢</p><p>伤口较大：消毒敷料+加压包扎+就医</p><h2 id="骨折" tabindex="-1">骨折 <a class="header-anchor" href="#骨折" aria-label="Permalink to &quot;骨折&quot;">​</a></h2><h2 id="过敏性休克急救" tabindex="-1">过敏性休克急救 <a class="header-anchor" href="#过敏性休克急救" aria-label="Permalink to &quot;过敏性休克急救&quot;">​</a></h2><h2 id="药物中毒的识别与急救" tabindex="-1">药物中毒的识别与急救 <a class="header-anchor" href="#药物中毒的识别与急救" aria-label="Permalink to &quot;药物中毒的识别与急救&quot;">​</a></h2><h2 id="癫痫发作与昏厥处理" tabindex="-1">癫痫发作与昏厥处理 <a class="header-anchor" href="#癫痫发作与昏厥处理" aria-label="Permalink to &quot;癫痫发作与昏厥处理&quot;">​</a></h2><ol><li>防止受伤：移开周围的硬物</li><li>侧卧位</li></ol><h2 id="校园应急流程与法律保障" tabindex="-1">校园应急流程与法律保障 <a class="header-anchor" href="#校园应急流程与法律保障" aria-label="Permalink to &quot;校园应急流程与法律保障&quot;">​</a></h2><ol><li>目击者立即评估，拨打120</li><li>通知校园急救</li><li>现场初步急救</li><li>派人到校门引导救护车</li><li>通知辅导员/老师</li><li>通知家长</li></ol>',50)])])}const b=l(r,[["render",t]]);export{u as __pageData,b as default};
